BACKUP_DIR = os.path.join(BASE_DIR, "_update10_backup_" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S"))

FILES = {}

FILES['plans/models.py'] = 'from django.db import models\n\n\nFREQUENCY_PERIOD_CHOICES = [\n    (\'day\', \'dziennie\'),\n    (\'week\', \'w tygodniu\'),\n    (\'month\', \'w miesiacu\'),\n]\n\n\ndef format_frequency(freq_min, freq_max, period):\n    """Buduje czytelny tekst czestotliwosci, np. \'3x w tygodniu\' albo\n    \'0-1x w tygodniu\'. Zwraca pusty string jesli brak danych."""\n    if freq_min is None and freq_max is None:\n        return \'\'\n    period_label = dict(FREQUENCY_PERIOD_CHOICES).get(period, period)\n    if freq_max is None or freq_max == freq_min:\n        value = freq_min if freq_min is not None else freq_max\n        return f"{value}x {period_label}"\n    if freq_min is None:\n        return f"{freq_max}x {period_label}"\n    return f"{freq_min}-{freq_max}x {period_label}"\n\n\nclass PlanTemplate(models.Model):\n    """Szablon planu treningowego - wielokrotnego uzytku. Trener moze\n    \'wystartowac\' od szablonu tworzac nowy plan dla konkretnego psa -\n    dane sa KOPIOWANE (nie linkowane), wiec modyfikacje planu NIE wplywaja\n    na szablon i odwrotnie."""\n    name = models.CharField(max_length=200, verbose_name="Nazwa szablonu")\n    training_goal = models.TextField(blank=True, verbose_name="Cel treningu")\n    safety_rules = models.TextField(blank=True, verbose_name="Wazne zasady i bezpieczenstwo")\n    is_active = models.BooleanField(default=True, verbose_name="Aktywny")\n\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        ordering = [\'name\']\n        verbose_name = "Szablon planu"\n        verbose_name_plural = "Szablony planow"\n\n    def __str__(self):\n        return self.name\n\n\nclass TemplateExerciseSet(models.Model):\n    """Zestaw cwiczen wewnatrz szablonu planu (np. \'Zestaw 1\')."""\n    template = models.ForeignKey(\n        PlanTemplate, related_name=\'exercise_sets\', on_delete=models.CASCADE\n    )\n    name = models.CharField(max_length=100, verbose_name="Nazwa zestawu", default="Zestaw 1")\n    frequency_min = models.PositiveSmallIntegerField(null=True, blank=True, verbose_name="Czestotliwosc od")\n    frequency_max = models.PositiveSmallIntegerField(null=True, blank=True, verbose_name="Czestotliwosc do")\n    frequency_period = models.CharField(\n        max_length=10, choices=FREQUENCY_PERIOD_CHOICES, default=\'week\', verbose_name="Okres"\n    )\n    order = models.PositiveIntegerField(default=0, verbose_name="Kolejnosc")\n\n    class Meta:\n        ordering = [\'order\', \'pk\']\n        verbose_name = "Zestaw cwiczen (szablon)"\n        verbose_name_plural = "Zestawy cwiczen (szablon)"\n\n    def __str__(self):\n        return f"{self.name} ({self.template.name})"\n\n    def get_frequency_display_text(self):\n        return format_frequency(self.frequency_min, self.frequency_max, self.frequency_period)\n\n\nclass TemplatePlanExercise(models.Model):\n    """Pozycja cwiczenia wewnatrz zestawu szablonu."""\n    exercise_set = models.ForeignKey(\n        TemplateExerciseSet, related_name=\'plan_exercises\', on_delete=models.CASCADE\n    )\n    exercise = models.ForeignKey(\n        \'exercises.Exercise\', on_delete=models.PROTECT, related_name=\'template_usages\',\n        verbose_name="Cwiczenie"\n    )\n    order = models.PositiveIntegerField(default=0, verbose_name="Kolejnosc")\n    goal_text = models.TextField(blank=True, verbose_name="Cel")\n    execution_text = models.TextField(blank=True, verbose_name="Wykonanie")\n    reps_text = models.CharField(max_length=255, blank=True, verbose_name="Ilosc / powtorzenia")\n    notes_text = models.TextField(blank=True, verbose_name="Uwagi")\n\n    class Meta:\n        ordering = [\'order\', \'pk\']\n        verbose_name = "Cwiczenie w zestawie (szablon)"\n        verbose_name_plural = "Cwiczenia w zestawach (szablon)"\n\n    def __str__(self):\n        return f"{self.exercise.name} w {self.exercise_set}"\n\n\nclass TrainingPlan(models.Model):\n    STATUS_DRAFT = \'draft\'\n    STATUS_ACTIVE = \'active\'\n    STATUS_COMPLETED = \'completed\'\n    STATUS_CHOICES = [\n        (STATUS_DRAFT, \'Szkic\'),\n        (STATUS_ACTIVE, \'Aktywny\'),\n        (STATUS_COMPLETED, \'Zakonczony\'),\n    ]\n\n    dog = models.ForeignKey(\n        \'clients.Dog\', related_name=\'training_plans\', on_delete=models.CASCADE, verbose_name="Pies"\n    )\n    name = models.CharField(max_length=200, verbose_name="Nazwa planu")\n    status = models.CharField(\n        max_length=10, choices=STATUS_CHOICES, default=STATUS_DRAFT, verbose_name="Status"\n    )\n    training_goal = models.TextField(blank=True, verbose_name="Cel treningu")\n    safety_rules = models.TextField(blank=True, verbose_name="Wazne zasady i bezpieczenstwo")\n    created_from_template = models.ForeignKey(\n        PlanTemplate, null=True, blank=True, on_delete=models.SET_NULL,\n        related_name=\'plans_created\', verbose_name="Utworzony z szablonu"\n    )\n    is_active = models.BooleanField(default=True, verbose_name="Aktywny (archiwizacja)")\n\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        ordering = [\'-created_at\']\n        verbose_name = "Plan treningowy"\n        verbose_name_plural = "Plany treningowe"\n\n    def __str__(self):\n        return f"{self.name} ({self.dog.name})"\n\n    def get_conflicts(self):\n        """Zwraca liste (plan_exercise, shared_tags) dla kazdego cwiczenia\n        w tym planie, ktore ma wspolny tag zdrowotny z psem. Uzywane do\n        ostrzezen na stronie planu/psa."""\n        conflicts = []\n        for ex_set in self.exercise_sets.all():\n            for pe in ex_set.plan_exercises.all():\n                shared = self.dog.get_shared_tags(pe.exercise)\n                if shared:\n                    conflicts.append((pe, shared))\n        return conflicts\n\n\nclass ExerciseSet(models.Model):\n    """Zestaw cwiczen wewnatrz konkretnego planu treningowego psa."""\n    plan = models.ForeignKey(\n        TrainingPlan, related_name=\'exercise_sets\', on_delete=models.CASCADE\n    )\n    name = models.CharField(max_length=100, verbose_name="Nazwa zestawu", default="Zestaw 1")\n    frequency_min = models.PositiveSmallIntegerField(null=True, blank=True, verbose_name="Czestotliwosc od")\n    frequency_max = models.PositiveSmallIntegerField(null=True, blank=True, verbose_name="Czestotliwosc do")\n    frequency_period = models.CharField(\n        max_length=10, choices=FREQUENCY_PERIOD_CHOICES, default=\'week\', verbose_name="Okres"\n    )\n    order = models.PositiveIntegerField(default=0, verbose_name="Kolejnosc")\n\n    class Meta:\n        ordering = [\'order\', \'pk\']\n        verbose_name = "Zestaw cwiczen"\n        verbose_name_plural = "Zestawy cwiczen"\n\n    def __str__(self):\n        return f"{self.name} ({self.plan.name})"\n\n    def get_frequency_display_text(self):\n        return format_frequency(self.frequency_min, self.frequency_max, self.frequency_period)\n\n\nclass PlanExercise(models.Model):\n    """Pozycja cwiczenia wewnatrz zestawu konkretnego planu."""\n    exercise_set = models.ForeignKey(\n        ExerciseSet, related_name=\'plan_exercises\', on_delete=models.CASCADE\n    )\n    exercise = models.ForeignKey(\n        \'exercises.Exercise\', on_delete=models.PROTECT, related_name=\'plan_usages\',\n        verbose_name="Cwiczenie"\n    )\n    order = models.PositiveIntegerField(default=0, verbose_name="Kolejnosc")\n    goal_text = models.TextField(blank=True, verbose_name="Cel")\n    execution_text = models.TextField(blank=True, verbose_name="Wykonanie")\n    reps_text = models.CharField(max_length=255, blank=True, verbose_name="Ilosc / powtorzenia")\n    notes_text = models.TextField(blank=True, verbose_name="Uwagi")\n\n    class Meta:\n        ordering = [\'order\', \'pk\']\n        verbose_name = "Cwiczenie w zestawie"\n        verbose_name_plural = "Cwiczenia w zestawach"\n\n    def __str__(self):\n        return f"{self.exercise.name} w {self.exercise_set}"\n'
FILES['plans/views.py'] = 'from django.shortcuts import render, redirect, get_object_or_404\nfrom django.contrib import messages\nfrom django.contrib.auth.decorators import login_required\nfrom django.db.models import Q\nfrom django.core.paginator import Paginator\n\nfrom clients.models import Dog\nfrom exercises.models import Exercise, MuscleGroup\nfrom .models import TrainingPlan, ExerciseSet, PlanExercise, PlanTemplate\nfrom .forms import TrainingPlanForm, ExerciseSetForm, PlanExerciseForm\n\nEXERCISES_PER_PAGE = 20\n\n\n# ============ TRAINING PLAN ============\n\n@login_required\ndef plan_list(request, dog_pk):\n    dog = get_object_or_404(Dog, pk=dog_pk)\n    plans = dog.training_plans.filter(is_active=True)\n    templates = PlanTemplate.objects.filter(is_active=True)\n    return render(request, \'plans/plan_list.html\', {\n        \'dog\': dog,\n        \'plans\': plans,\n        \'templates\': templates,\n    })\n\n\n@login_required\ndef plan_create_blank(request, dog_pk):\n    dog = get_object_or_404(Dog, pk=dog_pk)\n    if request.method == \'POST\':\n        form = TrainingPlanForm(request.POST)\n        if form.is_valid():\n            plan = form.save(commit=False)\n            plan.dog = dog\n            plan.save()\n            messages.success(request, f\'Plan "{plan.name}" zostal utworzony.\')\n            return redirect(\'plan_detail\', pk=plan.pk)\n    else:\n        form = TrainingPlanForm()\n    return render(request, \'plans/plan_form.html\', {\n        \'form\': form,\n        \'dog\': dog,\n        \'title\': \'Nowy plan od zera\',\n    })\n\n\n@login_required\ndef plan_create_from_template(request, dog_pk):\n    dog = get_object_or_404(Dog, pk=dog_pk)\n    templates = PlanTemplate.objects.filter(is_active=True)\n\n    if request.method == \'POST\':\n        template_id = request.POST.get(\'template\')\n        template = get_object_or_404(PlanTemplate, pk=template_id, is_active=True)\n\n        plan = TrainingPlan.objects.create(\n            dog=dog,\n            name=f"{template.name} - {dog.name}",\n            status=TrainingPlan.STATUS_DRAFT,\n            training_goal=template.training_goal,\n            safety_rules=template.safety_rules,\n            created_from_template=template,\n        )\n\n        for t_set in template.exercise_sets.all():\n            new_set = ExerciseSet.objects.create(\n                plan=plan,\n                name=t_set.name,\n                frequency_min=t_set.frequency_min,\n                frequency_max=t_set.frequency_max,\n                frequency_period=t_set.frequency_period,\n                order=t_set.order,\n            )\n            for t_pe in t_set.plan_exercises.all():\n                PlanExercise.objects.create(\n                    exercise_set=new_set,\n                    exercise=t_pe.exercise,\n                    order=t_pe.order,\n                    goal_text=t_pe.goal_text,\n                    execution_text=t_pe.execution_text,\n                    reps_text=t_pe.reps_text,\n                    notes_text=t_pe.notes_text,\n                )\n\n        messages.success(request, f\'Plan zostal utworzony na podstawie szablonu "{template.name}". Mozesz go teraz zmodyfikowac.\')\n        return redirect(\'plan_detail\', pk=plan.pk)\n\n    return render(request, \'plans/plan_create_from_template.html\', {\n        \'dog\': dog,\n        \'templates\': templates,\n    })\n\n\n@login_required\ndef plan_detail(request, pk):\n    plan = get_object_or_404(TrainingPlan, pk=pk)\n    conflicts = plan.get_conflicts()\n    conflict_pks = {pe.pk for pe, _tags in conflicts}\n    return render(request, \'plans/plan_detail.html\', {\n        \'plan\': plan,\n        \'dog\': plan.dog,\n        \'conflicts\': conflicts,\n        \'conflict_pks\': conflict_pks,\n    })\n\n\n@login_required\ndef plan_update(request, pk):\n    plan = get_object_or_404(TrainingPlan, pk=pk)\n    if request.method == \'POST\':\n        form = TrainingPlanForm(request.POST, instance=plan)\n        if form.is_valid():\n            form.save()\n            messages.success(request, \'Plan zostal zaktualizowany.\')\n            return redirect(\'plan_detail\', pk=plan.pk)\n    else:\n        form = TrainingPlanForm(instance=plan)\n    return render(request, \'plans/plan_form.html\', {\n        \'form\': form,\n        \'dog\': plan.dog,\n        \'plan\': plan,\n        \'title\': \'Edytuj plan\',\n    })\n\n\n@login_required\ndef plan_delete(request, pk):\n    plan = get_object_or_404(TrainingPlan, pk=pk)\n    if request.method == \'POST\':\n        plan.is_active = False\n        plan.save()\n        messages.success(request, \'Plan zostal przeniesiony do archiwum.\')\n        return redirect(\'plan_list\', dog_pk=plan.dog.pk)\n    return render(request, \'plans/plan_confirm_delete.html\', {\'plan\': plan})\n\n\n@login_required\ndef plan_archived_list(request, dog_pk):\n    dog = get_object_or_404(Dog, pk=dog_pk)\n    plans = dog.training_plans.filter(is_active=False).order_by(\'-updated_at\')\n    return render(request, \'plans/plan_archived_list.html\', {\'dog\': dog, \'plans\': plans})\n\n\n@login_required\ndef plan_restore(request, pk):\n    plan = get_object_or_404(TrainingPlan, pk=pk, is_active=False)\n    if request.method == \'POST\':\n        plan.is_active = True\n        plan.save()\n        messages.success(request, \'Plan zostal przywrocony.\')\n    return redirect(\'plan_archived_list\', dog_pk=plan.dog.pk)\n\n\n@login_required\ndef plan_delete_permanent(request, pk):\n    plan = get_object_or_404(TrainingPlan, pk=pk, is_active=False)\n    dog_pk = plan.dog.pk\n    if request.method == \'POST\':\n        plan.delete()\n        messages.success(request, \'Plan zostal usuniety na zawsze.\')\n    return redirect(\'plan_archived_list\', dog_pk=dog_pk)\n\n\n# ============ EXERCISE SET ============\n\n@login_required\ndef set_create(request, plan_pk):\n    plan = get_object_or_404(TrainingPlan, pk=plan_pk)\n    if request.method == \'POST\':\n        form = ExerciseSetForm(request.POST)\n        if form.is_valid():\n            exercise_set = form.save(commit=False)\n            exercise_set.plan = plan\n            exercise_set.order = plan.exercise_sets.count()\n            exercise_set.save()\n            messages.success(request, f\'Zestaw "{exercise_set.name}" zostal dodany.\')\n            return redirect(\'plan_detail\', pk=plan.pk)\n    else:\n        default_name = f"Zestaw {plan.exercise_sets.count() + 1}"\n        form = ExerciseSetForm(initial={\'name\': default_name})\n    return render(request, \'plans/set_form.html\', {\n        \'form\': form,\n        \'plan\': plan,\n        \'title\': \'Dodaj zestaw cwiczen\',\n    })\n\n\n@login_required\ndef set_update(request, pk):\n    exercise_set = get_object_or_404(ExerciseSet, pk=pk)\n    if request.method == \'POST\':\n        form = ExerciseSetForm(request.POST, instance=exercise_set)\n        if form.is_valid():\n            form.save()\n            messages.success(request, \'Zestaw zostal zaktualizowany.\')\n            return redirect(\'plan_detail\', pk=exercise_set.plan.pk)\n    else:\n        form = ExerciseSetForm(instance=exercise_set)\n    return render(request, \'plans/set_form.html\', {\n        \'form\': form,\n        \'plan\': exercise_set.plan,\n        \'exercise_set\': exercise_set,\n        \'title\': \'Edytuj zestaw\',\n    })\n\n\n@login_required\ndef set_delete(request, pk):\n    exercise_set = get_object_or_404(ExerciseSet, pk=pk)\n    plan_pk = exercise_set.plan.pk\n    if request.method == \'POST\':\n        exercise_set.delete()\n        messages.success(request, \'Zestaw zostal usuniety.\')\n        return redirect(\'plan_detail\', pk=plan_pk)\n    return render(request, \'plans/set_confirm_delete.html\', {\'exercise_set\': exercise_set})\n\n\n@login_required\ndef set_move_up(request, pk):\n    exercise_set = get_object_or_404(ExerciseSet, pk=pk)\n    if request.method == \'POST\':\n        siblings = list(exercise_set.plan.exercise_sets.order_by(\'order\', \'pk\'))\n        idx = siblings.index(exercise_set)\n        if idx > 0:\n            prev_set = siblings[idx - 1]\n            exercise_set.order, prev_set.order = prev_set.order, exercise_set.order\n            exercise_set.save()\n            prev_set.save()\n    return redirect(\'plan_detail\', pk=exercise_set.plan.pk)\n\n\n@login_required\ndef set_move_down(request, pk):\n    exercise_set = get_object_or_404(ExerciseSet, pk=pk)\n    if request.method == \'POST\':\n        siblings = list(exercise_set.plan.exercise_sets.order_by(\'order\', \'pk\'))\n        idx = siblings.index(exercise_set)\n        if idx < len(siblings) - 1:\n            next_set = siblings[idx + 1]\n            exercise_set.order, next_set.order = next_set.order, exercise_set.order\n            exercise_set.save()\n            next_set.save()\n    return redirect(\'plan_detail\', pk=exercise_set.plan.pk)\n\n\n# ============ PLAN EXERCISE (wybor z katalogu + edycja) ============\n\n@login_required\ndef plan_exercise_select(request, set_pk):\n    exercise_set = get_object_or_404(ExerciseSet, pk=set_pk)\n    dog = exercise_set.plan.dog\n\n    exercises = Exercise.objects.filter(is_active=True).prefetch_related(\n        \'muscle_groups\', \'contraindication_tags\'\n    )\n\n    search_query = request.GET.get(\'q\', \'\').strip()\n    muscle_group_filter = request.GET.get(\'muscle_group\', \'\').strip()\n\n    if search_query:\n        exercises = exercises.filter(\n            Q(name__icontains=search_query) | Q(description__icontains=search_query) |\n            Q(variant_name__icontains=search_query)\n        )\n    if muscle_group_filter:\n        exercises = exercises.filter(muscle_groups__id=muscle_group_filter)\n\n    exercises = exercises.distinct().order_by(\'name\')\n\n    paginator = Paginator(exercises, EXERCISES_PER_PAGE)\n    page_obj = paginator.get_page(request.GET.get(\'page\'))\n\n    dog_tag_ids = set(dog.health_tags.values_list(\'pk\', flat=True))\n    for ex in page_obj:\n        ex_tag_ids = set(ex.contraindication_tags.values_list(\'pk\', flat=True))\n        ex.shared_tag_names = [\n            t.name for t in ex.contraindication_tags.all() if t.pk in dog_tag_ids\n        ]\n\n    return render(request, \'plans/plan_exercise_select.html\', {\n        \'exercise_set\': exercise_set,\n        \'dog\': dog,\n        \'page_obj\': page_obj,\n        \'search_query\': search_query,\n        \'muscle_group_filter\': muscle_group_filter,\n        \'muscle_groups\': MuscleGroup.objects.all(),\n    })\n\n\n@login_required\ndef plan_exercise_add(request, set_pk, exercise_pk):\n    exercise_set = get_object_or_404(ExerciseSet, pk=set_pk)\n    exercise = get_object_or_404(Exercise, pk=exercise_pk)\n    dog = exercise_set.plan.dog\n\n    if request.method == \'POST\':\n        shared_tags = dog.get_shared_tags(exercise)\n\n        plan_exercise = PlanExercise.objects.create(\n            exercise_set=exercise_set,\n            exercise=exercise,\n            order=exercise_set.plan_exercises.count(),\n            goal_text=\'\',\n            execution_text=exercise.description,\n            reps_text=\'\',\n            notes_text=\'\',\n        )\n\n        if shared_tags:\n            tag_names = \', \'.join(t.name for t in shared_tags)\n            messages.warning(\n                request,\n                f\'Uwaga: cwiczenie "{exercise.name}" ma tagi wspolne z profilem zdrowotnym \'\n                f\'{dog.name}: {tag_names}. Sprawdz, czy to bezpieczne dla tego psa.\'\n            )\n        messages.success(request, f\'Cwiczenie "{exercise.name}" zostalo dodane do zestawu.\')\n        return redirect(\'plan_exercise_update\', pk=plan_exercise.pk)\n\n    return redirect(\'plan_exercise_select\', set_pk=exercise_set.pk)\n\n\n@login_required\ndef plan_exercise_update(request, pk):\n    plan_exercise = get_object_or_404(PlanExercise, pk=pk)\n    plan = plan_exercise.exercise_set.plan\n    dog = plan.dog\n    shared_tags = dog.get_shared_tags(plan_exercise.exercise)\n\n    if request.method == \'POST\':\n        form = PlanExerciseForm(request.POST, instance=plan_exercise)\n        if form.is_valid():\n            form.save()\n            messages.success(request, \'Cwiczenie w planie zostalo zaktualizowane.\')\n            return redirect(\'plan_detail\', pk=plan.pk)\n    else:\n        form = PlanExerciseForm(instance=plan_exercise)\n\n    return render(request, \'plans/plan_exercise_form.html\', {\n        \'form\': form,\n        \'plan_exercise\': plan_exercise,\n        \'plan\': plan,\n        \'shared_tags\': shared_tags,\n    })\n\n\n@login_required\ndef plan_exercise_delete(request, pk):\n    plan_exercise = get_object_or_404(PlanExercise, pk=pk)\n    plan_pk = plan_exercise.exercise_set.plan.pk\n    if request.method == \'POST\':\n        plan_exercise.delete()\n        messages.success(request, \'Cwiczenie zostalo usuniete z zestawu.\')\n    return redirect(\'plan_detail\', pk=plan_pk)\n\n\n@login_required\ndef plan_exercise_move_up(request, pk):\n    plan_exercise = get_object_or_404(PlanExercise, pk=pk)\n    if request.method == \'POST\':\n        siblings = list(plan_exercise.exercise_set.plan_exercises.order_by(\'order\', \'pk\'))\n        idx = siblings.index(plan_exercise)\n        if idx > 0:\n            prev_pe = siblings[idx - 1]\n            plan_exercise.order, prev_pe.order = prev_pe.order, plan_exercise.order\n            plan_exercise.save()\n            prev_pe.save()\n    return redirect(\'plan_detail\', pk=plan_exercise.exercise_set.plan.pk)\n\n\n@login_required\ndef plan_exercise_move_down(request, pk):\n    plan_exercise = get_object_or_404(PlanExercise, pk=pk)\n    if request.method == \'POST\':\n        siblings = list(plan_exercise.exercise_set.plan_exercises.order_by(\'order\', \'pk\'))\n        idx = siblings.index(plan_exercise)\n        if idx < len(siblings) - 1:\n            next_pe = siblings[idx + 1]\n            plan_exercise.order, next_pe.order = next_pe.order, plan_exercise.order\n            plan_exercise.save()\n            next_pe.save()\n    return redirect(\'plan_detail\', pk=plan_exercise.exercise_set.plan.pk)\n'
FILES['plans/forms.py'] = 'from django import forms\nfrom django.core.exceptions import ValidationError\nfrom .models import (\n    TrainingPlan, ExerciseSet, PlanExercise,\n    PlanTemplate, TemplateExerciseSet, TemplatePlanExercise,\n    FREQUENCY_PERIOD_CHOICES,\n)\n\n\nclass TrainingPlanForm(forms.ModelForm):\n    class Meta:\n        model = TrainingPlan\n        fields = [\'name\', \'status\', \'training_goal\', \'safety_rules\']\n        widgets = {\n            \'name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. Plan kondycyjny - jesien 2026\'}),\n            \'status\': forms.Select(attrs={\'class\': \'form-select\'}),\n            \'training_goal\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 3, \'placeholder\': \'Na czym skupia sie ten plan...\'}),\n            \'safety_rules\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 4, \'placeholder\': \'Jedna zasada na linie...\'}),\n        }\n\n    def clean_name(self):\n        name = self.cleaned_data.get(\'name\', \'\').strip()\n        if len(name) < 3:\n            raise ValidationError(\'Nazwa planu musi miec przynajmniej 3 znaki.\')\n        return name\n\n\nclass ExerciseSetForm(forms.ModelForm):\n    class Meta:\n        model = ExerciseSet\n        fields = [\'name\', \'frequency_min\', \'frequency_max\', \'frequency_period\']\n        widgets = {\n            \'name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. Zestaw 1\'}),\n            \'frequency_min\': forms.NumberInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. 3\', \'min\': 0}),\n            \'frequency_max\': forms.NumberInput(attrs={\'class\': \'form-control\', \'placeholder\': \'opcjonalnie, np. 4\', \'min\': 0}),\n            \'frequency_period\': forms.Select(attrs={\'class\': \'form-select\'}),\n        }\n\n    def clean(self):\n        cleaned = super().clean()\n        fmin = cleaned.get(\'frequency_min\')\n        fmax = cleaned.get(\'frequency_max\')\n        if fmin is not None and fmax is not None and fmax < fmin:\n            self.add_error(\'frequency_max\', \'Wartosc "do" nie moze byc mniejsza niz "od".\')\n        return cleaned\n\n\nclass PlanExerciseForm(forms.ModelForm):\n    class Meta:\n        model = PlanExercise\n        fields = [\'goal_text\', \'execution_text\', \'reps_text\', \'notes_text\']\n        widgets = {\n            \'goal_text\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 2, \'placeholder\': \'Co chcemy osiagnac tym cwiczeniem u tego psa...\'}),\n            \'execution_text\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 3, \'placeholder\': \'Jak wykonac cwiczenie...\'}),\n            \'reps_text\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. 6-10x, 15-60 sek\'}),\n            \'notes_text\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 2, \'placeholder\': \'Uwagi specyficzne dla tego psa...\'}),\n        }\n\n\nclass PlanTemplateForm(forms.ModelForm):\n    class Meta:\n        model = PlanTemplate\n        fields = [\'name\', \'training_goal\', \'safety_rules\']\n        widgets = {\n            \'name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. Plan dla psa z dysplazja\'}),\n            \'training_goal\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 3}),\n            \'safety_rules\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 4}),\n        }\n\n    def clean_name(self):\n        name = self.cleaned_data.get(\'name\', \'\').strip()\n        if len(name) < 3:\n            raise ValidationError(\'Nazwa szablonu musi miec przynajmniej 3 znaki.\')\n        return name\n'
FILES['plans/urls.py'] = "from django.urls import path\nfrom . import views\n\nurlpatterns = [\n    # Plany (zagniezdzone pod psem)\n    path('dogs/<int:dog_pk>/plans/', views.plan_list, name='plan_list'),\n    path('dogs/<int:dog_pk>/plans/add/', views.plan_create_blank, name='plan_create_blank'),\n    path('dogs/<int:dog_pk>/plans/add-from-template/', views.plan_create_from_template, name='plan_create_from_template'),\n    path('dogs/<int:dog_pk>/plans/archived/', views.plan_archived_list, name='plan_archived_list'),\n\n    path('plans/<int:pk>/', views.plan_detail, name='plan_detail'),\n    path('plans/<int:pk>/edit/', views.plan_update, name='plan_update'),\n    path('plans/<int:pk>/delete/', views.plan_delete, name='plan_delete'),\n    path('plans/<int:pk>/restore/', views.plan_restore, name='plan_restore'),\n    path('plans/<int:pk>/delete-permanent/', views.plan_delete_permanent, name='plan_delete_permanent'),\n\n    # Zestawy cwiczen\n    path('plans/<int:plan_pk>/sets/add/', views.set_create, name='set_create'),\n    path('sets/<int:pk>/edit/', views.set_update, name='set_update'),\n    path('sets/<int:pk>/delete/', views.set_delete, name='set_delete'),\n    path('sets/<int:pk>/move-up/', views.set_move_up, name='set_move_up'),\n    path('sets/<int:pk>/move-down/', views.set_move_down, name='set_move_down'),\n\n    # Cwiczenia w zestawach\n    path('sets/<int:set_pk>/exercises/select/', views.plan_exercise_select, name='plan_exercise_select'),\n    path('sets/<int:set_pk>/exercises/add/<int:exercise_pk>/', views.plan_exercise_add, name='plan_exercise_add'),\n    path('plan-exercises/<int:pk>/edit/', views.plan_exercise_update, name='plan_exercise_update'),\n    path('plan-exercises/<int:pk>/delete/', views.plan_exercise_delete, name='plan_exercise_delete'),\n    path('plan-exercises/<int:pk>/move-up/', views.plan_exercise_move_up, name='plan_exercise_move_up'),\n    path('plan-exercises/<int:pk>/move-down/', views.plan_exercise_move_down, name='plan_exercise_move_down'),\n]\n"
FILES['plans/admin.py'] = "from django.contrib import admin\nfrom .models import (\n    TrainingPlan, ExerciseSet, PlanExercise,\n    PlanTemplate, TemplateExerciseSet, TemplatePlanExercise,\n)\n\n\nclass PlanExerciseInline(admin.TabularInline):\n    model = PlanExercise\n    extra = 1\n    fields = ('exercise', 'order', 'goal_text', 'reps_text')\n\n\nclass ExerciseSetInline(admin.TabularInline):\n    model = ExerciseSet\n    extra = 1\n    fields = ('name', 'frequency_min', 'frequency_max', 'frequency_period', 'order')\n    show_change_link = True\n\n\n@admin.register(TrainingPlan)\nclass TrainingPlanAdmin(admin.ModelAdmin):\n    list_display = ('name', 'dog', 'status', 'is_active', 'created_from_template', 'created_at')\n    list_filter = ('status', 'is_active')\n    search_fields = ('name', 'dog__name')\n    inlines = [ExerciseSetInline]\n\n\n@admin.register(ExerciseSet)\nclass ExerciseSetAdmin(admin.ModelAdmin):\n    list_display = ('name', 'plan', 'frequency_min', 'frequency_max', 'frequency_period', 'order')\n    inlines = [PlanExerciseInline]\n\n\nclass TemplatePlanExerciseInline(admin.TabularInline):\n    model = TemplatePlanExercise\n    extra = 1\n    fields = ('exercise', 'order', 'goal_text', 'reps_text')\n\n\nclass TemplateExerciseSetInline(admin.TabularInline):\n    model = TemplateExerciseSet\n    extra = 1\n    fields = ('name', 'frequency_min', 'frequency_max', 'frequency_period', 'order')\n    show_change_link = True\n\n\n@admin.register(PlanTemplate)\nclass PlanTemplateAdmin(admin.ModelAdmin):\n    list_display = ('name', 'is_active', 'created_at')\n    list_filter = ('is_active',)\n    search_fields = ('name',)\n    inlines = [TemplateExerciseSetInline]\n\n\n@admin.register(TemplateExerciseSet)\nclass TemplateExerciseSetAdmin(admin.ModelAdmin):\n    list_display = ('name', 'template', 'order')\n    inlines = [TemplatePlanExerciseInline]\n"
FILES['plans/apps.py'] = "from django.apps import AppConfig\n\n\nclass PlansConfig(AppConfig):\n    default_auto_field = 'django.db.models.BigAutoField'\n    name = 'plans'\n"
