FILES['plans/migrations/__init__.py'] = ''
FILES['plans/templates/plans/plan_list.html'] = '{% extends \'base.html\' %}\n{% block title %}Plany - {{ dog.name }}{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-3">\n    <h1><i class="bi bi-clipboard2-pulse" style="color: #D4AF37;"></i> Plany treningowe - {{ dog.name }}</h1>\n    <div>\n        <a href="{% url \'plan_archived_list\' dog.pk %}" class="btn btn-outline-secondary me-2">\n            <i class="bi bi-archive"></i> Archiwum\n        </a>\n        <a href="{% url \'dog_detail\' dog.pk %}" class="btn btn-secondary">\n            <i class="bi bi-arrow-left"></i> Powrot do psa\n        </a>\n    </div>\n</div>\n\n<div class="form-card mb-4">\n    <h5 class="mb-3">Dodaj nowy plan</h5>\n    <a href="{% url \'plan_create_blank\' dog.pk %}" class="btn btn-primary me-2">\n        <i class="bi bi-plus-lg"></i> Nowy plan od zera\n    </a>\n    {% if templates %}\n        <a href="{% url \'plan_create_from_template\' dog.pk %}" class="btn btn-outline-primary">\n            <i class="bi bi-file-earmark-text"></i> Nowy plan od szablonu\n        </a>\n    {% endif %}\n</div>\n\n<div class="row">\n    {% for plan in plans %}\n    <div class="col-md-4 mb-4">\n        <div class="card exercise-card">\n            <div class="card-body">\n                <h5 class="card-title">\n                    {{ plan.name }}\n                    <span class="badge\n                        {% if plan.status == \'active\' %}bg-success\n                        {% elif plan.status == \'draft\' %}bg-secondary\n                        {% else %}bg-dark{% endif %}">\n                        {{ plan.get_status_display }}\n                    </span>\n                </h5>\n                <p class="text-muted small mb-1">\n                    <i class="bi bi-calendar"></i> {{ plan.created_at|date:"d.m.Y" }}\n                </p>\n                <p class="text-muted small mb-0">\n                    <i class="bi bi-list-ol"></i> {{ plan.exercise_sets.count }} zestaw(y)\n                </p>\n                {% if plan.created_from_template %}\n                    <p class="text-muted small mb-0"><i class="bi bi-file-earmark-text"></i> Z szablonu: {{ plan.created_from_template.name }}</p>\n                {% endif %}\n            </div>\n            <div class="card-footer bg-white border-0 pb-3">\n                <a href="{% url \'plan_detail\' plan.pk %}" class="btn btn-sm btn-primary">\n                    <i class="bi bi-eye"></i> Szczegoly\n                </a>\n                <a href="{% url \'plan_update\' plan.pk %}" class="btn btn-sm btn-outline-secondary">\n                    <i class="bi bi-pencil"></i>\n                </a>\n                <a href="{% url \'plan_delete\' plan.pk %}" class="btn btn-sm btn-outline-danger">\n                    <i class="bi bi-archive"></i>\n                </a>\n            </div>\n        </div>\n    </div>\n    {% empty %}\n    <div class="col-12">\n        <div class="empty-state">\n            <i class="bi bi-inbox"></i>\n            <p class="mb-3">Ten pies nie ma jeszcze zadnego planu treningowego.</p>\n        </div>\n    </div>\n    {% endfor %}\n</div>\n{% endblock %}\n'
FILES['plans/templates/plans/plan_form.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ title }}{% endblock %}\n\n{% block content %}\n<h1 class="mb-4">{{ title }} - {{ dog.name }}</h1>\n\n<div class="form-card">\n    <form method="post">\n        {% csrf_token %}\n        {% if form.non_field_errors %}\n            <div class="alert alert-danger">{{ form.non_field_errors }}</div>\n        {% endif %}\n\n        <div class="mb-3">\n            <label class="form-label">Nazwa planu</label>\n            {{ form.name }}\n            {% if form.name.errors %}<div class="invalid-feedback-custom">{{ form.name.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Status</label>\n            {{ form.status }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Cel treningu (ogolny dla calego planu)</label>\n            {{ form.training_goal }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Wazne zasady i bezpieczenstwo</label>\n            {{ form.safety_rules }}\n        </div>\n\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Zapisz</button>\n            {% if plan %}\n                <a href="{% url \'plan_detail\' plan.pk %}" class="btn btn-secondary">Anuluj</a>\n            {% else %}\n                <a href="{% url \'plan_list\' dog.pk %}" class="btn btn-secondary">Anuluj</a>\n            {% endif %}\n        </div>\n    </form>\n</div>\n{% endblock %}\n'
FILES['plans/templates/plans/plan_confirm_delete.html'] = '{% extends \'base.html\' %}\n{% block title %}Archiwizuj plan{% endblock %}\n\n{% block content %}\n<div class="form-card">\n    <h1 class="mb-4"><i class="bi bi-archive text-warning"></i> Przenies do archiwum</h1>\n    <p>Czy na pewno chcesz przeniesc plan <strong>{{ plan.name }}</strong> do archiwum?</p>\n    <form method="post">\n        {% csrf_token %}\n        <button type="submit" class="btn btn-danger"><i class="bi bi-archive"></i> Tak, przenies do archiwum</button>\n        <a href="{% url \'plan_detail\' plan.pk %}" class="btn btn-secondary">Anuluj</a>\n    </form>\n</div>\n{% endblock %}\n'
FILES['plans/templates/plans/plan_archived_list.html'] = '{% extends \'base.html\' %}\n{% block title %}Archiwum planow{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-4">\n    <h1><i class="bi bi-archive"></i> Archiwum planow - {{ dog.name }}</h1>\n    <a href="{% url \'plan_list\' dog.pk %}" class="btn btn-secondary">\n        <i class="bi bi-arrow-left"></i> Powrot do listy\n    </a>\n</div>\n\n<div class="form-card">\n    <table class="table">\n        <thead>\n            <tr><th>Nazwa</th><th>Status</th><th>Zarchiwizowano</th><th>Akcje</th></tr>\n        </thead>\n        <tbody>\n            {% for plan in plans %}\n            <tr>\n                <td>{{ plan.name }}</td>\n                <td>{{ plan.get_status_display }}</td>\n                <td>{{ plan.updated_at|date:"d.m.Y H:i" }}</td>\n                <td>\n                    <form method="post" action="{% url \'plan_restore\' plan.pk %}" style="display:inline;">\n                        {% csrf_token %}\n                        <button type="submit" class="btn btn-sm btn-outline-secondary">\n                            <i class="bi bi-arrow-counterclockwise"></i> Przywroc\n                        </button>\n                    </form>\n                    <form method="post" action="{% url \'plan_delete_permanent\' plan.pk %}" style="display:inline;" onsubmit="return confirm(\'Czy na pewno chcesz usunac ten plan NA ZAWSZE?\');">\n                        {% csrf_token %}\n                        <button type="submit" class="btn btn-sm btn-outline-danger">\n                            <i class="bi bi-trash"></i> Usun na zawsze\n                        </button>\n                    </form>\n                </td>\n            </tr>\n            {% empty %}\n            <tr><td colspan="4" class="text-center text-muted">Archiwum jest puste.</td></tr>\n            {% endfor %}\n        </tbody>\n    </table>\n</div>\n{% endblock %}\n'
FILES['plans/templates/plans/plan_create_from_template.html'] = '{% extends \'base.html\' %}\n{% block title %}Nowy plan od szablonu{% endblock %}\n\n{% block content %}\n<h1 class="mb-4">Nowy plan od szablonu - {{ dog.name }}</h1>\n\n<div class="form-card">\n    <form method="post">\n        {% csrf_token %}\n        <div class="mb-3">\n            <label class="form-label">Wybierz szablon</label>\n            <select name="template" class="form-select" required>\n                <option value="">-- wybierz --</option>\n                {% for t in templates %}\n                    <option value="{{ t.pk }}">{{ t.name }} ({{ t.exercise_sets.count }} zestaw(y))</option>\n                {% endfor %}\n            </select>\n            <small class="text-muted">\n                Struktura szablonu (zestawy i cwiczenia) zostanie skopiowana do nowego planu.\n                Mozesz ja potem swobodnie modyfikowac - zmiany NIE wplyna na szablon.\n            </small>\n        </div>\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Utworz plan</button>\n            <a href="{% url \'plan_list\' dog.pk %}" class="btn btn-secondary">Anuluj</a>\n        </div>\n    </form>\n</div>\n{% endblock %}\n'
FILES['plans/templates/plans/plan_detail.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ plan.name }}{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-3">\n    <h1>\n        {{ plan.name }}\n        <span class="badge\n            {% if plan.status == \'active\' %}bg-success\n            {% elif plan.status == \'draft\' %}bg-secondary\n            {% else %}bg-dark{% endif %}">\n            {{ plan.get_status_display }}\n        </span>\n    </h1>\n    <div>\n        <a href="{% url \'plan_update\' plan.pk %}" class="btn btn-outline-secondary">\n            <i class="bi bi-pencil"></i> Edytuj\n        </a>\n        <a href="{% url \'plan_delete\' plan.pk %}" class="btn btn-outline-danger">\n            <i class="bi bi-archive"></i> Archiwizuj\n        </a>\n        <a href="{% url \'plan_list\' dog.pk %}" class="btn btn-secondary">\n            <i class="bi bi-arrow-left"></i> Powrot do listy planow\n        </a>\n    </div>\n</div>\n\n<p class="text-muted"><i class="bi bi-suit-heart-fill"></i> Pies: <a href="{% url \'dog_detail\' dog.pk %}">{{ dog.name }}</a></p>\n\n{% if conflicts %}\n<div class="alert alert-warning">\n    <i class="bi bi-exclamation-triangle-fill"></i>\n    <strong>Uwaga - mozliwe konflikty zdrowotne:</strong>\n    <ul class="mb-0 mt-2">\n        {% for pe, shared_tags in conflicts %}\n            <li>\n                "{{ pe.exercise.name }}" ({{ pe.exercise_set.name }}) - wspolne tagi:\n                {% for tag in shared_tags %}<span class="badge bg-warning text-dark">{{ tag.name }}</span>{% endfor %}\n            </li>\n        {% endfor %}\n    </ul>\n</div>\n{% endif %}\n\n{% if plan.training_goal %}\n<div class="detail-section mb-3">\n    <h5><i class="bi bi-bullseye"></i> Cel treningu</h5>\n    <p>{{ plan.training_goal|linebreaks }}</p>\n</div>\n{% endif %}\n\n{% if plan.safety_rules %}\n<div class="detail-section mb-4">\n    <h5><i class="bi bi-shield-check"></i> Wazne zasady i bezpieczenstwo</h5>\n    <p>{{ plan.safety_rules|linebreaks }}</p>\n</div>\n{% endif %}\n\n<div class="d-flex justify-content-between align-items-center mb-3">\n    <h4>Zestawy cwiczen</h4>\n    <a href="{% url \'set_create\' plan.pk %}" class="btn btn-primary">\n        <i class="bi bi-plus-lg"></i> Dodaj zestaw\n    </a>\n</div>\n\n{% for exercise_set in plan.exercise_sets.all %}\n<div class="detail-section mb-4">\n    <div class="d-flex justify-content-between align-items-center mb-3">\n        <h5 class="mb-0">\n            {{ exercise_set.name }}\n            {% if exercise_set.get_frequency_display_text %}\n                <span class="text-muted small">&mdash; wykonuj {{ exercise_set.get_frequency_display_text }}</span>\n            {% endif %}\n        </h5>\n        <div>\n            <form method="post" action="{% url \'set_move_up\' exercise_set.pk %}" style="display:inline;">\n                {% csrf_token %}\n                <button type="submit" class="btn btn-sm btn-outline-secondary"><i class="bi bi-arrow-up"></i></button>\n            </form>\n            <form method="post" action="{% url \'set_move_down\' exercise_set.pk %}" style="display:inline;">\n                {% csrf_token %}\n                <button type="submit" class="btn btn-sm btn-outline-secondary"><i class="bi bi-arrow-down"></i></button>\n            </form>\n            <a href="{% url \'set_update\' exercise_set.pk %}" class="btn btn-sm btn-outline-secondary"><i class="bi bi-pencil"></i></a>\n            <a href="{% url \'plan_exercise_select\' exercise_set.pk %}" class="btn btn-sm btn-primary">\n                <i class="bi bi-plus-lg"></i> Dodaj cwiczenie\n            </a>\n            <a href="{% url \'set_delete\' exercise_set.pk %}" class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></a>\n        </div>\n    </div>\n\n    <table class="table table-sm">\n        <thead>\n            <tr><th>Cwiczenie</th><th>Ilosc</th><th>Akcje</th></tr>\n        </thead>\n        <tbody>\n            {% for pe in exercise_set.plan_exercises.all %}\n            <tr>\n                <td>\n                    {{ pe.exercise.name }}\n                    {% if pe.pk in conflict_pks %}\n                        <i class="bi bi-exclamation-triangle-fill text-warning" title="Mozliwy konflikt zdrowotny"></i>\n                    {% endif %}\n                </td>\n                <td class="small text-muted">{{ pe.reps_text|default:"-" }}</td>\n                <td>\n                    <form method="post" action="{% url \'plan_exercise_move_up\' pe.pk %}" style="display:inline;">\n                        {% csrf_token %}\n                        <button type="submit" class="btn btn-sm btn-outline-secondary"><i class="bi bi-arrow-up"></i></button>\n                    </form>\n                    <form method="post" action="{% url \'plan_exercise_move_down\' pe.pk %}" style="display:inline;">\n                        {% csrf_token %}\n                        <button type="submit" class="btn btn-sm btn-outline-secondary"><i class="bi bi-arrow-down"></i></button>\n                    </form>\n                    <a href="{% url \'plan_exercise_update\' pe.pk %}" class="btn btn-sm btn-outline-secondary"><i class="bi bi-pencil"></i></a>\n                    <form method="post" action="{% url \'plan_exercise_delete\' pe.pk %}" style="display:inline;">\n                        {% csrf_token %}\n                        <button type="submit" class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button>\n                    </form>\n                </td>\n            </tr>\n            {% empty %}\n            <tr><td colspan="3" class="text-center text-muted">Brak cwiczen w tym zestawie.</td></tr>\n            {% endfor %}\n        </tbody>\n    </table>\n</div>\n{% empty %}\n<div class="empty-state">\n    <i class="bi bi-inbox"></i>\n    <p>Ten plan nie ma jeszcze zadnego zestawu cwiczen.</p>\n</div>\n{% endfor %}\n{% endblock %}\n'
FILES['plans/templates/plans/set_form.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ title }}{% endblock %}\n\n{% block content %}\n<h1 class="mb-4">{{ title }}</h1>\n<p class="text-muted">Plan: <strong>{{ plan.name }}</strong></p>\n\n<div class="form-card">\n    <form method="post">\n        {% csrf_token %}\n        {% if form.non_field_errors %}\n            <div class="alert alert-danger">{{ form.non_field_errors }}</div>\n        {% endif %}\n\n        <div class="mb-3">\n            <label class="form-label">Nazwa zestawu</label>\n            {{ form.name }}\n        </div>\n\n        <div class="row">\n            <div class="col-md-4 mb-3">\n                <label class="form-label">Czestotliwosc od</label>\n                {{ form.frequency_min }}\n            </div>\n            <div class="col-md-4 mb-3">\n                <label class="form-label">Czestotliwosc do (opcjonalnie)</label>\n                {{ form.frequency_max }}\n                {% if form.frequency_max.errors %}<div class="invalid-feedback-custom">{{ form.frequency_max.errors|first }}</div>{% endif %}\n            </div>\n            <div class="col-md-4 mb-3">\n                <label class="form-label">Okres</label>\n                {{ form.frequency_period }}\n            </div>\n        </div>\n        <small class="text-muted">np. "od 3" + okres "w tygodniu" = "3x w tygodniu"; "od 0, do 1" = "0-1x w tygodniu"</small>\n\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Zapisz</button>\n            <a href="{% url \'plan_detail\' plan.pk %}" class="btn btn-secondary">Anuluj</a>\n        </div>\n    </form>\n</div>\n{% endblock %}\n'
FILES['plans/templates/plans/set_confirm_delete.html'] = '{% extends \'base.html\' %}\n{% block title %}Usun zestaw{% endblock %}\n\n{% block content %}\n<div class="form-card">\n    <h1 class="mb-4"><i class="bi bi-trash text-danger"></i> Usun zestaw</h1>\n    <p>Czy na pewno chcesz usunac zestaw <strong>{{ exercise_set.name }}</strong> wraz z {{ exercise_set.plan_exercises.count }} cwiczeniami?</p>\n    <p class="text-muted">Ta operacja jest nieodwracalna.</p>\n    <form method="post">\n        {% csrf_token %}\n        <button type="submit" class="btn btn-danger"><i class="bi bi-trash"></i> Tak, usun</button>\n        <a href="{% url \'plan_detail\' exercise_set.plan.pk %}" class="btn btn-secondary">Anuluj</a>\n    </form>\n</div>\n{% endblock %}\n'
FILES['plans/templates/plans/plan_exercise_form.html'] = '{% extends \'base.html\' %}\n{% block title %}Edytuj cwiczenie w planie{% endblock %}\n\n{% block content %}\n<h1 class="mb-4"><i class="bi bi-pencil"></i> {{ plan_exercise.exercise.name }}</h1>\n<p class="text-muted">\n    Plan: <strong>{{ plan.name }}</strong> | Zestaw: <strong>{{ plan_exercise.exercise_set.name }}</strong>\n</p>\n\n{% if shared_tags %}\n<div class="alert alert-warning">\n    <i class="bi bi-exclamation-triangle-fill"></i>\n    <strong>Uwaga:</strong> to cwiczenie ma tagi wspolne z profilem zdrowotnym {{ plan.dog.name }}:\n    {% for tag in shared_tags %}<span class="badge bg-warning text-dark">{{ tag.name }}</span>{% endfor %}\n    Sprawdz, czy to bezpieczne.\n</div>\n{% endif %}\n\n<div class="form-card">\n    <form method="post">\n        {% csrf_token %}\n        {% if form.non_field_errors %}\n            <div class="alert alert-danger">{{ form.non_field_errors }}</div>\n        {% endif %}\n\n        <div class="mb-3">\n            <label class="form-label">Cel (dlaczego to cwiczenie u tego psa)</label>\n            {{ form.goal_text }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Wykonanie</label>\n            {{ form.execution_text }}\n            <small class="text-muted">Domyslnie skopiowane z opisu cwiczenia w katalogu - mozesz dostosowac.</small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Ilosc / powtorzenia</label>\n            {{ form.reps_text }}\n            <small class="text-muted">np. "6-10x, 15-60 sek", "2-3 minuty", "10-20 przejsc" - wolny tekst, bo format bardzo zalezy od cwiczenia.</small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Uwagi specyficzne dla tego psa</label>\n            {{ form.notes_text }}\n        </div>\n\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Zapisz</button>\n            <a href="{% url \'plan_detail\' plan.pk %}" class="btn btn-secondary">Anuluj</a>\n        </div>\n    </form>\n</div>\n{% endblock %}\n'
FILES['plans/templates/plans/plan_exercise_select.html'] = '{% extends \'base.html\' %}\n{% block title %}Wybierz cwiczenie{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-3">\n    <h1><i class="bi bi-search"></i> Wybierz cwiczenie</h1>\n    <a href="{% url \'plan_detail\' exercise_set.plan.pk %}" class="btn btn-secondary">\n        <i class="bi bi-arrow-left"></i> Powrot do planu\n    </a>\n</div>\n<p class="text-muted">Zestaw: <strong>{{ exercise_set.name }}</strong> | Pies: <strong>{{ dog.name }}</strong></p>\n\n<div class="search-bar">\n    <form method="get" class="row g-2 align-items-center">\n        <div class="col-md-6">\n            <div class="input-group">\n                <span class="input-group-text bg-white border-0"><i class="bi bi-search"></i></span>\n                <input type="text" name="q" class="form-control border-0" placeholder="Szukaj po nazwie lub opisie..." value="{{ search_query }}">\n            </div>\n        </div>\n        <div class="col-md-4">\n            <select name="muscle_group" class="form-select" onchange="this.form.submit()">\n                <option value="">Grupa miesniowa: wszystkie</option>\n                {% for group in muscle_groups %}\n                    <option value="{{ group.id }}" {% if muscle_group_filter == group.id|stringformat:"s" %}selected{% endif %}>\n                        {{ group.name }}\n                    </option>\n                {% endfor %}\n            </select>\n        </div>\n        <div class="col-md-2">\n            <button type="submit" class="btn btn-primary w-100"><i class="bi bi-funnel"></i></button>\n        </div>\n    </form>\n</div>\n\n<div class="row">\n    {% for exercise in page_obj %}\n    <div class="col-md-4 mb-4">\n        <div class="card exercise-card">\n            <div class="card-body">\n                <h5 class="card-title">\n                    {{ exercise.name }}\n                    {% if exercise.shared_tag_names %}\n                        <i class="bi bi-exclamation-triangle-fill text-warning" title="Mozliwy konflikt: {{ exercise.shared_tag_names|join:\', \' }}"></i>\n                    {% endif %}\n                </h5>\n                <p class="card-text text-muted small">{{ exercise.description|truncatewords:15 }}</p>\n                {% if exercise.shared_tag_names %}\n                    <div class="mb-2">\n                        {% for tag_name in exercise.shared_tag_names %}\n                            <span class="badge bg-warning text-dark">{{ tag_name }}</span>\n                        {% endfor %}\n                    </div>\n                {% endif %}\n                <span class="badge badge-difficulty-{{ exercise.difficulty }}">{{ exercise.get_difficulty_display }}</span>\n            </div>\n            <div class="card-footer bg-white border-0 pb-3">\n                <form method="post" action="{% url \'plan_exercise_add\' exercise_set.pk exercise.pk %}">\n                    {% csrf_token %}\n                    <button type="submit" class="btn btn-sm btn-primary w-100">\n                        <i class="bi bi-plus-lg"></i> Dodaj do zestawu\n                    </button>\n                </form>\n            </div>\n        </div>\n    </div>\n    {% empty %}\n    <div class="col-12">\n        <div class="empty-state">\n            <i class="bi bi-inbox"></i>\n            <p>Nie znaleziono cwiczen spelniajacych kryteria.</p>\n        </div>\n    </div>\n    {% endfor %}\n</div>\n\n{% if page_obj.paginator.num_pages > 1 %}\n<nav class="d-flex justify-content-center mt-4">\n    <ul class="pagination">\n        {% if page_obj.has_previous %}\n            <li class="page-item"><a class="page-link" href="?page=1">&laquo;&laquo;</a></li>\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.previous_page_number }}">&laquo;</a></li>\n        {% endif %}\n        <li class="page-item disabled"><span class="page-link">Strona {{ page_obj.number }} z {{ page_obj.paginator.num_pages }}</span></li>\n        {% if page_obj.has_next %}\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.next_page_number }}">&raquo;</a></li>\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.paginator.num_pages }}">&raquo;&raquo;</a></li>\n        {% endif %}\n    </ul>\n</nav>\n{% endif %}\n{% endblock %}\n'
FILES['dogfitness/urls.py'] = "from django.contrib import admin\nfrom django.urls import path, include\nfrom django.conf import settings\nfrom django.conf.urls.static import static\nfrom django.contrib.auth import views as auth_views\n\nurlpatterns = [\n    path('admin/', admin.site.urls),\n    path('login/', auth_views.LoginView.as_view(template_name='registration/login.html'), name='login'),\n    path('logout/', auth_views.LogoutView.as_view(next_page='login'), name='logout'),\n    path('', include('exercises.urls')),\n    path('', include('clients.urls')),\n    path('', include('plans.urls')),\n]\n\nif settings.DEBUG:\n    urlpatterns += static(settings.MEDIA_URL, document_root=settings.MEDIA_ROOT)\n"
FILES['dogfitness/settings.py'] = "from pathlib import Path\nfrom decouple import config\n\nBASE_DIR = Path(__file__).resolve().parent.parent\n\nSECRET_KEY = config('SECRET_KEY')\nDEBUG = config('DEBUG', default=False, cast=bool)\nALLOWED_HOSTS = ['localhost', '127.0.0.1']\n\n# ============ CLOUDINARY (opcjonalny storage zdjec w chmurze) ============\n# Domyslnie WYLACZONE (USE_CLOUDINARY=False) - zdjecia trafiaja na dysk\n# lokalny serwera (jak dotychczas), zero zmian w dzialaniu aplikacji.\n#\n# Aby WLACZYC Cloudinary (trwaly storage w chmurze, darmowy plan 25GB):\n#   1. Zaloz darmowe konto na https://cloudinary.com\n#   2. Zainstaluj wymagane pakiety:\n#        pip install django-cloudinary-storage cloudinary\n#   3. W pliku .env ustaw:\n#        USE_CLOUDINARY=True\n#        CLOUDINARY_CLOUD_NAME=twoj_cloud_name\n#        CLOUDINARY_API_KEY=twoj_api_key\n#        CLOUDINARY_API_SECRET=twoj_api_secret\n#   4. Zrestartuj serwer (python manage.py runserver)\n#\n# Od tego momentu WSZYSTKIE nowo wgrywane zdjecia trafia do Cloudinary.\n# Zdjecia wgrane WCZESNIEJ (lokalnie) NIE zostana automatycznie przeniesione.\nUSE_CLOUDINARY = config('USE_CLOUDINARY', default=False, cast=bool)\n\nINSTALLED_APPS = [\n    'django.contrib.admin',\n    'django.contrib.auth',\n    'django.contrib.contenttypes',\n    'django.contrib.sessions',\n    'django.contrib.messages',\n]\n\nif USE_CLOUDINARY:\n    # 'cloudinary_storage' MUSI byc przed 'django.contrib.staticfiles'\n    INSTALLED_APPS += ['cloudinary_storage']\n\nINSTALLED_APPS += ['django.contrib.staticfiles']\n\nif USE_CLOUDINARY:\n    # 'cloudinary' MUSI byc po 'django.contrib.staticfiles'\n    INSTALLED_APPS += ['cloudinary']\n\nINSTALLED_APPS += ['exercises', 'clients', 'plans']\n\nMIDDLEWARE = [\n    'django.middleware.security.SecurityMiddleware',\n    'django.contrib.sessions.middleware.SessionMiddleware',\n    'django.middleware.common.CommonMiddleware',\n    'django.middleware.csrf.CsrfViewMiddleware',\n    'django.contrib.auth.middleware.AuthenticationMiddleware',\n    'django.contrib.messages.middleware.MessageMiddleware',\n    'django.middleware.clickjacking.XFrameOptionsMiddleware',\n]\n\nROOT_URLCONF = 'dogfitness.urls'\n\nTEMPLATES = [\n    {\n        'BACKEND': 'django.template.backends.django.DjangoTemplates',\n        'DIRS': [BASE_DIR / 'templates'],\n        'APP_DIRS': True,\n        'OPTIONS': {\n            'context_processors': [\n                'django.template.context_processors.debug',\n                'django.template.context_processors.request',\n                'django.contrib.auth.context_processors.auth',\n                'django.contrib.messages.context_processors.messages',\n            ],\n        },\n    },\n]\n\nWSGI_APPLICATION = 'dogfitness.wsgi.application'\n\nDATABASES = {\n    'default': {\n        'ENGINE': 'django.db.backends.postgresql',\n        'NAME': config('DB_NAME'),\n        'USER': config('DB_USER'),\n        'PASSWORD': config('DB_PASSWORD'),\n        'HOST': config('DB_HOST'),\n        'PORT': config('DB_PORT'),\n    }\n}\n\nLANGUAGE_CODE = 'pl'\nTIME_ZONE = 'Europe/Warsaw'\nUSE_I18N = True\nUSE_TZ = True\n\nSTATIC_URL = 'static/'\nSTATICFILES_DIRS = [BASE_DIR / 'static']\n\nMEDIA_URL = '/media/'\nMEDIA_ROOT = BASE_DIR / 'media'\n\nif USE_CLOUDINARY:\n    CLOUDINARY_STORAGE = {\n        'CLOUD_NAME': config('CLOUDINARY_CLOUD_NAME', default=''),\n        'API_KEY': config('CLOUDINARY_API_KEY', default=''),\n        'API_SECRET': config('CLOUDINARY_API_SECRET', default=''),\n    }\n    DEFAULT_FILE_STORAGE = 'cloudinary_storage.storage.MediaCloudinaryStorage'\n\nDEFAULT_AUTO_FIELD = 'django.db.models.BigAutoField'\n\n# ============ LOGOWANIE ============\nLOGIN_URL = 'login'\nLOGIN_REDIRECT_URL = 'exercise_list'\nLOGOUT_REDIRECT_URL = 'login'\n\n# ============ MONITOROWANIE MIEJSCA (Neon / storage dashboard) ============\n# Limit darmowego planu Neon dla calej bazy Postgres (w MB). Zmien jesli\n# masz inny plan / inny limit. UWAGA: ten limit dotyczy TYLKO bazy danych,\n# NIE dotyczy zdjec (pliki media sa na dysku serwera, np. Render, albo\n# w Cloudinary jesli USE_CLOUDINARY=True - to OSOBNE limity).\nNEON_DB_LIMIT_MB = 1024\n"
FILES['clients/templates/clients/dog_detail.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ dog.name }}{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-4">\n    <h1><i class="bi bi-suit-heart-fill"></i> {{ dog.name }}\n        {% if dog.training_status == \'paused\' %}\n            <span class="badge bg-warning text-dark">Trening wstrzymany</span>\n        {% endif %}\n    </h1>\n    <div>\n        <a href="{% url \'plan_list\' dog.pk %}" class="btn btn-primary">\n            <i class="bi bi-clipboard2-pulse"></i> Plany treningowe ({{ dog.training_plans.count }})\n        </a>\n        <a href="{% url \'dog_pdf\' dog.pk %}" target="_blank" class="btn btn-outline-secondary">\n            <i class="bi bi-file-pdf"></i> Karta PDF\n        </a>\n        <form method="post" action="{% url \'dog_toggle_training_status\' dog.pk %}" style="display:inline;">\n            {% csrf_token %}\n            {% if dog.training_status == \'paused\' %}\n                <button type="submit" class="btn btn-outline-success">\n                    <i class="bi bi-play-circle"></i> Przywroc trening\n                </button>\n            {% else %}\n                <button type="submit" class="btn btn-outline-warning">\n                    <i class="bi bi-pause-circle"></i> Wstrzymaj trening\n                </button>\n            {% endif %}\n        </form>\n        <a href="{% url \'dog_update\' dog.pk %}" class="btn btn-outline-secondary">\n            <i class="bi bi-pencil"></i> Edytuj\n        </a>\n        <a href="{% url \'dog_delete\' dog.pk %}" class="btn btn-outline-danger">\n            <i class="bi bi-archive"></i> Archiwizuj\n        </a>\n        <a href="{% url \'owner_detail\' dog.owner.pk %}" class="btn btn-secondary">\n            <i class="bi bi-arrow-left"></i> Powrot do wlasciciela\n        </a>\n    </div>\n</div>\n\n<div class="row">\n    <div class="col-md-4">\n        {% if dog.photo %}\n            <img src="{{ dog.photo.url }}" class="img-fluid rounded mb-3" alt="{{ dog.name }}">\n        {% else %}\n            <div class="card-img-placeholder mb-3" style="height:250px;"><i class="bi bi-image"></i></div>\n        {% endif %}\n    </div>\n    <div class="col-md-8">\n        <div class="detail-section">\n            <p><i class="bi bi-person"></i> Wlasciciel: <a href="{% url \'owner_detail\' dog.owner.pk %}">{{ dog.owner.full_name }}</a>\n                (<a href="tel:{{ dog.owner.phone }}">{{ dog.owner.phone }}</a>)\n            </p>\n            {% if dog.breed %}<p><i class="bi bi-tag"></i> Rasa: {{ dog.breed }}</p>{% endif %}\n            {% if dog.get_sex_display %}<p><i class="bi bi-gender-ambiguous"></i> Plec: {{ dog.get_sex_display }}</p>{% endif %}\n            {% if dog.get_age_display %}<p><i class="bi bi-cake2"></i> Wiek: {{ dog.get_age_display }}</p>{% endif %}\n            {% if dog.weight_kg %}<p><i class="bi bi-speedometer2"></i> Waga: {{ dog.weight_kg }} kg</p>{% endif %}\n\n            {% if dog.health_tags.all %}\n                <div class="mb-2">\n                    <strong class="small text-muted"><i class="bi bi-tags"></i> Tagi zdrowotne:</strong><br>\n                    {% for tag in dog.health_tags.all %}\n                        <span class="badge bg-warning text-dark">{{ tag.name }}</span>\n                    {% endfor %}\n                </div>\n            {% endif %}\n\n            {% if dog.health_notes %}\n                <div class="alert alert-warning mt-3">\n                    <i class="bi bi-exclamation-triangle-fill"></i>\n                    <strong>Informacje zdrowotne:</strong> {{ dog.health_notes|linebreaks }}\n                </div>\n            {% endif %}\n\n            {% if dog.trainer_notes %}\n                <hr>\n                <h6>Notatki trenera</h6>\n                <p>{{ dog.trainer_notes|linebreaks }}</p>\n            {% endif %}\n        </div>\n    </div>\n</div>\n{% endblock %}\n'


def main():
    print("=" * 70)
    print("DogFitness - _update10.py - MODUL: Plany treningowe (Etap 1)")
    print("=" * 70)

    if not os.path.exists(os.path.join(BASE_DIR, "manage.py")):
        print("!! UWAGA: nie znaleziono 'manage.py' w tym folderze.")
        sys.exit(1)

    if not os.path.exists(os.path.join(BASE_DIR, "clients")) or not os.path.exists(os.path.join(BASE_DIR, "exercises")):
        print("!! UWAGA: nie znaleziono folderow 'clients/' i/lub 'exercises/'.")
        print("   Ten skrypt wymaga wczesniej zastosowanych _update6.py..._update9.py!")
        sys.exit(1)

    backed_up_any = False

    for rel_path, content in FILES.items():
        full_path = os.path.join(BASE_DIR, rel_path.replace("/", os.sep))
        dir_path = os.path.dirname(full_path)

        if not os.path.exists(dir_path):
            os.makedirs(dir_path, exist_ok=True)
            print(f"[+] Utworzono folder: {dir_path}")

        if os.path.exists(full_path):
            backup_target = os.path.join(BACKUP_DIR, rel_path.replace("/", os.sep))
            os.makedirs(os.path.dirname(backup_target), exist_ok=True)
            shutil.copy2(full_path, backup_target)
            backed_up_any = True

        with open(full_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"[OK] Zapisano: {rel_path}")

    print("-" * 70)
    if backed_up_any:
        print(f"Kopie zapasowe nadpisanych plikow zapisano w:")
        print(f"  {BACKUP_DIR}")
    else:
        print("Nie bylo plikow do zbackupowania (wszystkie byly nowe).")

    print("-" * 70)
    print("GOTOWE! Nastepne kroki (WYMAGANE):")
    print("  1. python manage.py makemigrations plans")
    print("  2. python manage.py migrate")
    print("  3. python manage.py runserver")
    print("  4. Wejdz na strone psa - zobacz przycisk 'Plany treningowe'")
    print("=" * 70)


if __name__ == "__main__":
    main()
